/* Classic style for WampServer */

* {margin: 0;padding: 0;}

html {
	background: #ddd;
}

body {
	margin: 1em 3em;
	padding: 1em 3em;
	font: 80%/1.4 tahoma, arial, helvetica, lucida sans, sans-serif;
	border: 1px solid #999;
	background: #eee;
